<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Exceptions\BusinessRuleException; use App\Models\User; use App\Models\Subscription; use App\Support\ApiResponse; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class SubscriptionController extends Controller {
 public function index(Request $r){$v=$r->validate(['search'=>'nullable|string|max:255','status'=>'nullable|in:active,cancelled,past_due','per_page'=>'nullable|integer|min:5|max:100']);$q=Subscription::with(['user.role','plan'])->when($r->user()->role?->slug==='admin',fn($q)=>$q->whereHas('user.role',fn($q)=>$q->where('slug','!=','super_admin')))->when($v['search']??null,fn($q,$s)=>$q->whereHas('user',fn($q)=>$q->where('name','like',"%$s%")->orWhere('email','like',"%$s%")))->when($v['status']??null,fn($q,$s)=>$q->where('status',$s))->latest()->paginate($v['per_page']??15);return response()->json(['success'=>true,'data'=>$q]);}
 public function store(Request $r){$userId=$r->validate(['user_id'=>'required|exists:users,id'])['user_id'];$this->guard($r,User::findOrFail($userId));$s=Subscription::updateOrCreate(['user_id'=>$userId],$this->data($r));return ApiResponse::success(['subscription'=>$s->load(['user.role','plan'])],'Subscription saved successfully.',201);}
 public function show(Request $r,Subscription $subscription){$this->guard($r,$subscription->user);return ApiResponse::success(['subscription'=>$subscription->load(['user.role','plan'])]);}
 public function update(Request $r,Subscription $subscription){$this->guard($r,$subscription->user);$subscription->update($this->data($r));return ApiResponse::success(['subscription'=>$subscription->refresh()->load(['user.role','plan'])],'Subscription updated successfully.');}
 public function destroy(Request $r,Subscription $subscription){$this->guard($r,$subscription->user);$subscription->delete();return ApiResponse::success(message:'Subscription deleted successfully.');}
 public function mine(Request $r){return ApiResponse::success(['subscription'=>Subscription::with('plan')->where('user_id',$r->user()->id)->first()]);}
 public function updateMine(Request $r){$data=$r->validate(['plan_id'=>['required',Rule::exists('plans','id')->where('is_active',true)],'cancel_at_period_end'=>'sometimes|boolean']);$s=Subscription::updateOrCreate(['user_id'=>$r->user()->id],['plan_id'=>$data['plan_id'],'cancel_at_period_end'=>$data['cancel_at_period_end']??false,'status'=>'active','starts_at'=>now()]);return ApiResponse::success(['subscription'=>$s->load('plan')],'Subscription updated successfully.');}
 private function guard(Request $r,User $user){$user->loadMissing('role');if($r->user()->role?->slug==='admin'&&$user->role?->slug==='super_admin')throw new BusinessRuleException('Administrators cannot manage Super Administrators.',403);}
 private function data(Request $r){return $r->validate(['plan_id'=>'required|exists:plans,id','status'=>'required|in:active,cancelled,past_due','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at','cancel_at_period_end'=>'sometimes|boolean']);}
}
